  function dpr() { return Math.min(window.devicePixelRatio || 1, 2); }

  function drawThumb(canvas, grid, rows, cols, boxCss) {
    var d = dpr();
    var cell = boxCss / Math.max(rows, cols);
    var wCss = cols * cell, hCss = rows * cell;
    canvas.width = Math.round(wCss * d);
    canvas.height = Math.round(hCss * d);
    canvas.style.width = wCss + 'px';
    canvas.style.height = hCss + 'px';
    var ctx = canvas.getContext('2d');
    ctx.setTransform(d, 0, 0, d, 0, 0);
    ctx.imageSmoothingEnabled = false;
    ctx.clearRect(0, 0, wCss, hCss);
    for (var r = 0; r < rows; r++) {
      for (var c = 0; c < cols; c++) {
        var v = grid[r][c];
        if (v === 99) continue;
        ctx.fillStyle = PALETTE[v];
        ctx.fillRect(c * cell, r * cell, cell + 0.6, cell + 0.6);
      }
    }
  }

